  3	import com.fasterxml.jackson.databind.ObjectMapper;
  4	import com.fasterxml.jackson.databind.SerializationFeature;
  5	import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
  6	import com.pousada.api.*;
  7	import com.pousada.config.Database;
  8	import com.pousada.repository.MessageRepository;
  9	import com.pousada.repository.ReservationRepository;
 10	import com.pousada.repository.RoomRepository;
 11	import com.pousada.service.MessageService;
 12	import com.pousada.service.ReportService;
 13	import com.pousada.service.ReservationService;
 14	import com.pousada.service.RoomService;
 15	import com.pousada.service.messaging.*;
 16	import io.javalin.Javalin;
 17	import io.javalin.json.JavalinJackson;
 18	
 19	import java.util.ArrayList;
 20	import java.util.List;
 21	
 22	public class App {
 23	    public static void main(String[] args) {
 24	        String dbUrl = getEnv("DB_URL", "jdbc:postgresql://localhost:5432/pousada");
 25	        String dbUser = getEnv("DB_USER", "postgres");
 26	        String dbPassword = getEnv("DB_PASSWORD", "postgres");
 27	        int port = Integer.parseInt(getEnv("PORT", "7070"));
 28	        boolean testMode = Boolean.parseBoolean(getEnv("HOTEL_TEST_MODE", "false"));
 29	
 30	        Database database = new Database(dbUrl, dbUser, dbPassword);
 31	
 32	        RoomRepository roomRepository = new RoomRepository(database);
 33	        ReservationRepository reservationRepository = new ReservationRepository(database);
 34	        MessageRepository messageRepository = new MessageRepository(database);
 35	
 36	        MessageProcessor messageProcessor = createMessageProcessor(testMode);
 37	
 38	        MessageService messageService = new MessageService(messageRepository, messageProcessor);
 39	        RoomService roomService = new RoomService(roomRepository);
 40	        ReservationService reservationService = new ReservationService(
 41	            reservationRepository, roomRepository, messageService
 42	        );
 43	        ReportService reportService = new ReportService(reservationRepository, roomRepository);
 44	
 45	        RoomController roomController = new RoomController(roomService);
 46	        ReservationController reservationController = new ReservationController(reservationService);
 47	        MessageController messageController = new MessageController(messageService);
 48	        ReportController reportController = new ReportController(reportService);
 49	
 50	        ObjectMapper objectMapper = new ObjectMapper();
 51	        objectMapper.registerModule(new JavaTimeModule());
 52	        objectMapper.disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
 53	
 54	        Javalin app = Javalin.create(config -> {
 55	            config.jsonMapper(new JavalinJackson(objectMapper, true));
 56	        }).start(port);
 57	
 58	        app.get("/rooms", roomController::getRooms);
 59	
 60	        app.post("/reservations", reservationController::createReservation);
 61	        app.get("/reservations/{id}", reservationController::getReservation);
 62	        app.post("/reservations/{id}/confirmation", reservationController::confirmReservation);
 63	        app.post("/reservations/{id}/cancellation", reservationController::cancelReservation);
 64	        app.post("/reservations/{id}/check-in", reservationController::checkInReservation);
 65	        app.post("/reservations/{id}/check-out", reservationController::checkOutReservation);
 66	        app.get("/reservations/{id}/document", reservationController::getDocument);
 67	
 68	        app.get("/messages", messageController::getMessages);
 69	
 70	        app.get("/reports/occupancy", reportController::getOccupancyReport);
 71	        app.get("/reports/revenue", reportController::getRevenueReport);
 72	
 73	        Runtime.getRuntime().addShutdownHook(new Thread(database::close));
 74	    }
 75	
 76	    private static MessageProcessor createMessageProcessor(boolean testMode) {
 77	        List<MessageRule> rules = new ArrayList<>();
 78	
 79	        rules.add(new EmailValidationRule());
 80	
 81	        if (testMode) {
 82	            rules.add(new TestModeRule());
 83	        } else {
 84	            rules.add(new ArchiveCopyRule());
 85	        }
 86	
 87	        return new MessageProcessor(rules);
 88	    }
 89	
 90	    private static String getEnv(String name, String defaultValue) {
 91	        String value = System.getenv(name);
 92	        return value != null ? value : defaultValue;
 93	    }
 94	}
