110	public class MessageController {
111	    private final MessageService messageService;
112	
113	    public MessageController(MessageService messageService) {
114	        this.messageService = messageService;
115	    }
116	
117	    public void getMessages(Context ctx) {
118	        List<Message> messages = messageService.getAllMessages();
119	        List<Map<String, Object>> response = messages.stream()
120	            .map(message -> {
121	                Map<String, Object> map = new HashMap<>();
