124	                map.put("to", message.getTo());
125	                map.put("subject", message.getSubject());
126	                map.put("body", message.getBody());
127	                map.put("status", message.getStatus().name());
128	                return map;
129	            })
130	            .collect(Collectors.toList());
131	        ctx.json(response);
132	    }
133	}
