150	    public void getOccupancyReport(Context ctx) {
151	        try {
152	            String dateParam = ctx.queryParam("date");
153	            if (dateParam == null || dateParam.isEmpty()) {
154	                ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Missing date parameter"));
155	                return;
