188	package com.pousada.api;
189	
190	import com.fasterxml.jackson.databind.JsonNode;
191	import com.pousada.domain.RatePlan;
192	import com.pousada.domain.Reservation;
193	import com.pousada.domain.ReservationDocument;
194	import com.pousada.service.ReservationService;
195	import io.javalin.http.Context;
196	
197	import java.time.LocalDate;
198	import java.time.format.DateTimeParseException;
199	import java.util.HashMap;
200	import java.util.Map;
201	
202	public class ReservationController {
203	    private final ReservationService reservationService;
204	
205	    public ReservationController(ReservationService reservationService) {
206	        this.reservationService = reservationService;
207	    }
208	
209	    public void createReservation(Context ctx) {
210	        try {
211	            JsonNode json = ctx.bodyAsClass(JsonNode.class);
212	
213	            String roomNumber = getRequiredField(json, "roomNumber").asText();
214	            String guestName = getRequiredField(json, "guestName").asText();
215	            String guestEmail = getRequiredField(json, "guestEmail").asText();
216	            String guestCpf = getRequiredField(json, "guestCpf").asText();
217	            LocalDate checkIn = parseDate(getRequiredField(json, "checkIn").asText());
218	            LocalDate checkOut = parseDate(getRequiredField(json, "checkOut").asText());
219	            int guests = getRequiredField(json, "guests").asInt();
220	            RatePlan ratePlan = RatePlan.valueOf(getRequiredField(json, "ratePlan").asText());
221	
222	            if (!checkOut.isAfter(checkIn)) {
223	                throw new InvalidRequestException("Check-out must be after check-in");
224	            }
225	
226	            Reservation reservation = reservationService.createReservation(
227	                roomNumber, guestName, guestEmail, guestCpf,
228	                checkIn, checkOut, guests, ratePlan
229	            );
230	
231	            ctx.status(201).json(toMap(reservation));
232	
233	        } catch (NullPointerException | IllegalArgumentException e) {
234	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid request data"));
235	        } catch (DateTimeParseException e) {
236	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid date format"));
237	        } catch (ReservationService.RoomNotFoundException e) {
238	            ctx.status(404).json(new ErrorResponse("ROOM_NOT_FOUND", e.getMessage()));
239	        } catch (ReservationService.RoomUnavailableException e) {
240	            ctx.status(409).json(new ErrorResponse("ROOM_UNAVAILABLE", e.getMessage()));
241	        } catch (ReservationService.CapacityExceededException e) {
242	            ctx.status(422).json(new ErrorResponse("CAPACITY_EXCEEDED", e.getMessage()));
243	        } catch (ReservationService.InvalidRequestException e) {
244	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
245	        }
246	    }
247	
248	    public void getReservation(Context ctx) {
249	        try {
250	            Long id = Long.parseLong(ctx.pathParam("id"));
251	            Reservation reservation = reservationService.getReservation(id);
252	            ctx.json(toMap(reservation));
253	        } catch (ReservationService.ReservationNotFoundException e) {
254	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
255	        }
256	    }
257	
258	    public void confirmReservation(Context ctx) {
259	        try {
260	            Long id = Long.parseLong(ctx.pathParam("id"));
261	            Reservation reservation = reservationService.confirmReservation(id);
262	            ctx.json(toMap(reservation));
263	        } catch (ReservationService.ReservationNotFoundException e) {
264	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
265	        } catch (ReservationService.OperationNotAllowedException e) {
266	            ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", e.getMessage()));
267	        }
268	    }
269	
270	    public void cancelReservation(Context ctx) {
271	        try {
272	            Long id = Long.parseLong(ctx.pathParam("id"));
273	            Reservation reservation = reservationService.cancelReservation(id);
274	            ctx.json(toMap(reservation));
275	        } catch (ReservationService.ReservationNotFoundException e) {
276	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
277	        } catch (ReservationService.OperationNotAllowedException e) {
278	            ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", e.getMessage()));
279	        }
280	    }
281	
282	    public void checkInReservation(Context ctx) {
283	        try {
284	            Long id = Long.parseLong(ctx.pathParam("id"));
285	            Reservation reservation = reservationService.checkInReservation(id);
286	            ctx.json(toMap(reservation));
287	        } catch (ReservationService.ReservationNotFoundException e) {
288	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
289	        } catch (ReservationService.OperationNotAllowedException e) {
290	            ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", e.getMessage()));
291	        }
292	    }
293	
294	    public void checkOutReservation(Context ctx) {
295	        try {
296	            Long id = Long.parseLong(ctx.pathParam("id"));
297	            ReservationDocument document = reservationService.checkOutReservation(id);
298	            ctx.json(toDocumentMap(document));
299	        } catch (ReservationService.ReservationNotFoundException e) {
300	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
301	        } catch (ReservationService.OperationNotAllowedException e) {
302	            ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", e.getMessage()));
303	        }
304	    }
305	
306	    public void getDocument(Context ctx) {
307	        try {
308	            Long id = Long.parseLong(ctx.pathParam("id"));
309	            ReservationDocument document = reservationService.getDocument(id);
310	            ctx.json(toDocumentMap(document));
311	        } catch (ReservationService.ReservationNotFoundException e) {
312	            ctx.status(404).json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
313	        } catch (ReservationService.OperationNotAllowedException e) {
314	            ctx.status(409).json(new ErrorResponse("OPERATION_NOT_ALLOWED", e.getMessage()));
315	        }
316	    }
317	
318	    private JsonNode getRequiredField(JsonNode json, String fieldName) {
319	        JsonNode field = json.get(fieldName);
320	        if (field == null || field.isNull()) {
321	            throw new NullPointerException("Missing required field: " + fieldName);
322	        }
323	        return field;
324	    }
325	
326	    private LocalDate parseDate(String date) {
327	        try {
328	            return LocalDate.parse(date);
329	        } catch (DateTimeParseException e) {
330	            throw new DateTimeParseException("Invalid date format", date, 0);
331	        }
332	    }
333	
334	    private Map<String, Object> toMap(Reservation reservation) {
335	        Map<String, Object> map = new HashMap<>();
336	        map.put("id", reservation.getId());
337	        map.put("roomNumber", reservation.getRoomNumber());
338	        map.put("guestName", reservation.getGuestName());
339	        map.put("guestEmail", reservation.getGuestEmail());
340	        map.put("guestCpf", reservation.getGuestCpf());
341	        map.put("checkIn", reservation.getCheckIn());
342	        map.put("checkOut", reservation.getCheckOut());
343	        map.put("guests", reservation.getGuests());
344	        map.put("ratePlan", reservation.getRatePlan().name());
345	        map.put("nights", reservation.getNights());
346	        map.put("subtotal", reservation.getSubtotal());
347	        map.put("discount", reservation.getDiscount());
348	        map.put("total", reservation.getTotal());
349	        map.put("status", reservation.getStatus().name());
350	        map.put("amountPaid", reservation.getAmountPaid());
351	        map.put("refund", reservation.getRefund());
352	        return map;
353	    }
354	
355	    private Map<String, Object> toDocumentMap(ReservationDocument document) {
356	        Map<String, Object> map = new HashMap<>();
357	        map.put("title", document.getTitle());
358	        map.put("reservationId", document.getReservationId());
359	        map.put("guestName", document.getGuestName());
360	        map.put("guestCpf", document.getGuestCpf());
361	        map.put("roomNumber", document.getRoomNumber());
362	        map.put("roomType", document.getRoomType().name());
363	        map.put("checkIn", document.getCheckIn());
364	        map.put("checkOut", document.getCheckOut());
365	        map.put("nights", document.getNights());
366	        map.put("subtotal", document.getSubtotal());
367	        map.put("discount", document.getDiscount());
368	        map.put("total", document.getTotal());
369	        return map;
370	    }
371	
372	    private static class InvalidRequestException extends RuntimeException {
373	        public InvalidRequestException(String message) {
374	            super(message);
375	        }
376	    }
377	}
