209	    public void createReservation(Context ctx) {
210	        try {
211	            JsonNode json = ctx.bodyAsClass(JsonNode.class);
212	
213	            String roomNumber = getRequiredField(json, "roomNumber").asText();
214	            String guestName = getRequiredField(json, "guestName").asText();
215	            String guestEmail = getRequiredField(json, "guestEmail").asText();
216	            String guestCpf = getRequiredField(json, "guestCpf").asText();
217	            LocalDate checkIn = parseDate(getRequiredField(json, "checkIn").asText());
218	            LocalDate checkOut = parseDate(getRequiredField(json, "checkOut").asText());
219	            int guests = getRequiredField(json, "guests").asInt();
220	            RatePlan ratePlan = RatePlan.valueOf(getRequiredField(json, "ratePlan").asText());
221	
222	            if (!checkOut.isAfter(checkIn)) {
223	                throw new InvalidRequestException("Check-out must be after check-in");
224	            }
225	
226	            Reservation reservation = reservationService.createReservation(
227	                roomNumber, guestName, guestEmail, guestCpf,
228	                checkIn, checkOut, guests, ratePlan
229	            );
230	
231	            ctx.status(201).json(toMap(reservation));
232	
233	        } catch (NullPointerException | IllegalArgumentException e) {
234	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid request data"));
235	        } catch (DateTimeParseException e) {
236	            ctx.status(400).json(new ErrorResponse("INVALID_REQUEST", "Invalid date format"));
237	        } catch (ReservationService.RoomNotFoundException e) {
