 10	import java.util.List;
 11	
 12	public class MessageService {
 13	    private final MessageRepository messageRepository;
 14	    private final MessageProcessor messageProcessor;
 15	
 16	    public MessageService(MessageRepository messageRepository, MessageProcessor messageProcessor) {
 17	        this.messageRepository = messageRepository;
 18	        this.messageProcessor = messageProcessor;
 19	    }
 20	
 21	    public void send(MessageChannel channel, String to, String subject, String body) {
 22	        OutgoingMessage outgoing = new OutgoingMessage(channel, to, subject, body);
 23	        List<OutgoingMessage> processedMessages = messageProcessor.process(outgoing);
 24	
 25	        for (OutgoingMessage msg : processedMessages) {
 26	            MessageStatus status = msg.isBlocked() ? MessageStatus.BLOCKED : MessageStatus.SENT;
 27	            Message message = new Message(msg.getChannel(), msg.getTo(), msg.getSubject(), msg.getBody(), status);
 28	            messageRepository.save(message);
 29	        }
 30	    }
 31	
 32	    public List<Message> getAllMessages() {
 33	        return messageRepository.findAll();
 34	    }
 35	}
 36	package com.pousada.service;
 37	
 38	import com.pousada.domain.Reservation;
 39	import com.pousada.domain.Room;
 40	import com.pousada.repository.ReservationRepository;
 41	import com.pousada.repository.RoomRepository;
 42	
 43	import java.math.BigDecimal;
 44	import java.time.LocalDate;
 45	import java.time.YearMonth;
 46	import java.time.format.DateTimeFormatter;
 47	import java.util.List;
 48	import java.util.stream.Collectors;
 49	
 50	public class ReportService {
 51	    private final ReservationRepository reservationRepository;
 52	    private final RoomRepository roomRepository;
 53	
 54	    public ReportService(ReservationRepository reservationRepository, RoomRepository roomRepository) {
 55	        this.reservationRepository = reservationRepository;
 56	        this.roomRepository = roomRepository;
 57	    }
 58	
 59	    public String generateOccupancyReport(LocalDate date) {
 60	        List<Reservation> occupiedReservations = reservationRepository.findPaidByDate(date);
 61	        List<Room> allRooms = roomRepository.findAll();
 62	
 63	        StringBuilder csv = new StringBuilder();
 64	        csv.append("room,type,reservation,check_in,check_out\n");
 65	
 66	        DateTimeFormatter formatter = DateTimeFormatter.ofPattern("yyyy-MM-dd");
 67	
 68	        for (Reservation reservation : occupiedReservations) {
 69	            csv.append(String.format("%s,%s,%d,%s,%s\n",
 70	                reservation.getRoomNumber(),
 71	                getRoomType(reservation.getRoomNumber()),
 72	                reservation.getId(),
 73	                reservation.getCheckIn().format(formatter),
 74	                reservation.getCheckOut().format(formatter)
 75	            ));
 76	        }
 77	
 78	        csv.append(String.format("total,%d/%d\n", occupiedReservations.size(), allRooms.size()));
 79	
 80	        return csv.toString();
 81	    }
 82	
 83	    public String generateRevenueReport(YearMonth month) {
 84	        List<Reservation> reservations = reservationRepository.findRevenueByMonth(month);
 85	
 86	        StringBuilder csv = new StringBuilder();
 87	        csv.append("reservation,room,check_in,check_out,status,amount\n");
 88	
 89	        DateTimeFormatter formatter = DateTimeFormatter.ofPattern("yyyy-MM-dd");
 90	        BigDecimal total = BigDecimal.ZERO;
 91	
 92	        for (Reservation reservation : reservations) {
 93	            BigDecimal revenue = reservation.getAmountPaid();
 94	            if (reservation.getRefund() != null) {
 95	                revenue = revenue.subtract(reservation.getRefund());
 96	            }
 97	
 98	            csv.append(String.format("%d,%s,%s,%s,%s,%s\n",
 99	                reservation.getId(),
100	                reservation.getRoomNumber(),
101	                reservation.getCheckIn().format(formatter),
102	                reservation.getCheckOut().format(formatter),
103	                reservation.getStatus(),
104	                formatCsvMoney(revenue)
105	            ));
106	
107	            total = total.add(revenue);
108	        }
109	
110	        csv.append(String.format("total,%s\n", formatCsvMoney(total)));
111	
112	        return csv.toString();
113	    }
114	
115	    private String getRoomType(String roomNumber) {
116	        return roomRepository.findByNumber(roomNumber)
117	            .map(room -> room.getType().name())
118	            .orElse("UNKNOWN");
119	    }
120	
121	    private String formatCsvMoney(BigDecimal value) {
122	        return value.setScale(2).toPlainString();
123	    }
124	}
125	package com.pousada.service;
126	
127	import com.pousada.domain.*;
128	import com.pousada.repository.ReservationRepository;
129	import com.pousada.repository.RoomRepository;
130	
131	import java.math.BigDecimal;
132	import java.time.LocalDate;
133	import java.time.format.DateTimeFormatter;
134	import java.util.List;
135	import java.util.Optional;
136	
137	public class ReservationService {
138	    private final ReservationRepository reservationRepository;
139	    private final RoomRepository roomRepository;
140	    private final MessageService messageService;
141	
142	    public ReservationService(ReservationRepository reservationRepository,
143	                             RoomRepository roomRepository,
144	                             MessageService messageService) {
145	        this.reservationRepository = reservationRepository;
146	        this.roomRepository = roomRepository;
147	        this.messageService = messageService;
148	    }
149	
150	    public Reservation createReservation(String roomNumber, String guestName, String guestEmail,
151	                                        String guestCpf, LocalDate checkIn, LocalDate checkOut,
152	                                        int guests, RatePlan ratePlan) {
153	        Room room = roomRepository.findByNumber(roomNumber)
154	            .orElseThrow(() -> new RoomNotFoundException(roomNumber));
155	
156	        if (guests > room.getCapacity()) {
157	            throw new CapacityExceededException(guests, room.getCapacity());
158	        }
159	
160	        if (guests < 1) {
161	            throw new InvalidRequestException("At least one guest is required");
162	        }
163	
164	        List<Reservation> conflicts = reservationRepository.findByRoomAndDateRange(roomNumber, checkIn, checkOut);
165	        if (!conflicts.isEmpty()) {
166	            throw new RoomUnavailableException(roomNumber, checkIn, checkOut);
167	        }
168	
169	        Reservation reservation = new Reservation(
170	            roomNumber, guestName, guestEmail, guestCpf,
171	            checkIn, checkOut, guests, ratePlan,
172	            room.getNightlyRate()
173	        );
174	
175	        return reservationRepository.save(reservation);
176	    }
177	
178	    public Reservation getReservation(Long id) {
179	        return reservationRepository.findById(id)
180	            .orElseThrow(() -> new ReservationNotFoundException(id));
181	    }
182	
183	    public Reservation confirmReservation(Long id) {
184	        Reservation reservation = getReservation(id);
185	
186	        if (!reservation.getStatus().canConfirm()) {
187	            throw new OperationNotAllowedException("Cannot confirm reservation in status " + reservation.getStatus());
188	        }
189	
190	        reservation.confirm();
191	        reservationRepository.save(reservation);
192	
193	        sendConfirmationEmail(reservation);
194	
195	        return reservation;
196	    }
197	
198	    private void sendConfirmationEmail(Reservation reservation) {
199	        ReservationDocument document = createDocument(reservation);
200	        String documentText = formatDocument(document);
201	
202	        String emailBody = String.format(
203	            """
204	            Olá, %s!
205	
206	            Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:
207	
208	            %s
209	
210	            A entrada é a partir das 14h, e a saída, até as 12h.
211	            Até breve!""",
212	            reservation.getGuestName(),
213	            documentText
214	        );
215	
216	        messageService.send(
217	            MessageChannel.EMAIL,
218	            reservation.getGuestEmail(),
219	            "Reserva confirmada - Pousada Maré Alta",
220	            emailBody
221	        );
222	    }
223	
224	    public Reservation cancelReservation(Long id) {
225	        Reservation reservation = getReservation(id);
226	
227	        if (!reservation.getStatus().canCancel()) {
228	            throw new OperationNotAllowedException("Cannot cancel reservation in status " + reservation.getStatus());
229	        }
230	
231	        reservation.cancel();
232	        return reservationRepository.save(reservation);
233	    }
234	
235	    public Reservation checkInReservation(Long id) {
236	        Reservation reservation = getReservation(id);
237	
238	        if (!reservation.getStatus().canCheckIn()) {
239	            throw new OperationNotAllowedException("Cannot check-in reservation in status " + reservation.getStatus());
240	        }
241	
242	        reservation.checkIn();
243	        return reservationRepository.save(reservation);
244	    }
245	
246	    public ReservationDocument checkOutReservation(Long id) {
247	        Reservation reservation = getReservation(id);
248	
249	        if (!reservation.getStatus().canCheckOut()) {
250	            throw new OperationNotAllowedException("Cannot check-out reservation in status " + reservation.getStatus());
251	        }
252	
253	        reservation.checkOut();
254	        reservationRepository.save(reservation);
255	
256	        return createDocument(reservation);
257	    }
258	
259	    public ReservationDocument getDocument(Long id) {
260	        Reservation reservation = getReservation(id);
261	
262	        if (!reservation.getStatus().isPaid()) {
263	            throw new OperationNotAllowedException("Document is only available for paid reservations");
264	        }
265	
266	        return createDocument(reservation);
267	    }
268	
269	    private ReservationDocument createDocument(Reservation reservation) {
270	        Room room = roomRepository.findByNumber(reservation.getRoomNumber()).orElseThrow();
271	
272	        return new ReservationDocument(
273	            "Comprovante de reserva",
274	            reservation.getId(),
275	            reservation.getGuestName(),
276	            reservation.getGuestCpf(),
277	            reservation.getRoomNumber(),
278	            room.getType(),
279	            reservation.getCheckIn(),
280	            reservation.getCheckOut(),
281	            reservation.getNights(),
282	            reservation.getSubtotal(),
283	            reservation.getDiscount(),
284	            reservation.getTotal()
285	        );
286	    }
287	
288	    private String formatDocument(ReservationDocument doc) {
289	        DateTimeFormatter dateFormatter = DateTimeFormatter.ofPattern("dd/MM/yyyy");
290	
291	        String cpf = formatCpf(doc.getGuestCpf());
292	        String checkIn = doc.getCheckIn().format(dateFormatter);
293	        String checkOut = doc.getCheckOut().format(dateFormatter);
294	        String nights = doc.getNights() == 1 ? "1 diária" : doc.getNights() + " diárias";
295	        String subtotal = formatMoney(doc.getSubtotal());
296	
297	        StringBuilder sb = new StringBuilder();
298	        sb.append(String.format("Comprovante de reserva nº %d\n", doc.getReservationId()));
299	        sb.append(String.format("Hóspede: %s (CPF %s)\n", doc.getGuestName(), cpf));
300	        sb.append(String.format("Quarto: %s (%s)\n", doc.getRoomNumber(), doc.getRoomType()));
301	        sb.append(String.format("Entrada: %s | Saída: %s | %s\n", checkIn, checkOut, nights));
302	        sb.append(String.format("Diárias: %s\n", subtotal));
303	
304	        if (doc.getDiscount().compareTo(BigDecimal.ZERO) > 0) {
305	            sb.append(String.format("Desconto: %s\n", formatMoney(doc.getDiscount())));
306	        }
307	
308	        sb.append(String.format("Total: %s", formatMoney(doc.getTotal())));
309	
310	        return sb.toString();
311	    }
312	
313	    private String formatCpf(String cpf) {
314	        if (cpf.length() == 11) {
315	            return String.format("%s.%s.%s-%s",
316	                cpf.substring(0, 3),
317	                cpf.substring(3, 6),
318	                cpf.substring(6, 9),
319	                cpf.substring(9, 11));
320	        }
321	        return cpf;
322	    }
323	
324	    private String formatMoney(BigDecimal value) {
325	        return String.format("R$ %,.2f", value).replace(',', 'X').replace('.', ',').replace('X', '.');
326	    }
327	
328	    public static class RoomNotFoundException extends RuntimeException {
329	        public RoomNotFoundException(String roomNumber) {
330	            super("Room not found: " + roomNumber);
331	        }
332	    }
333	
334	    public static class ReservationNotFoundException extends RuntimeException {
335	        public ReservationNotFoundException(Long id) {
336	            super("Reservation not found: " + id);
337	        }
338	    }
339	
340	    public static class RoomUnavailableException extends RuntimeException {
341	        public RoomUnavailableException(String roomNumber, LocalDate from, LocalDate to) {
342	            super(String.format("Room %s is not available from %s to %s", roomNumber, from, to));
343	        }
344	    }
345	
346	    public static class CapacityExceededException extends RuntimeException {
347	        public CapacityExceededException(int requested, int capacity) {
348	            super(String.format("Requested %d guests exceeds room capacity of %d", requested, capacity));
349	        }
350	    }
351	
352	    public static class OperationNotAllowedException extends RuntimeException {
353	        public OperationNotAllowedException(String message) {
354	            super(message);
355	        }
356	    }
357	
358	    public static class InvalidRequestException extends RuntimeException {
359	        public InvalidRequestException(String message) {
360	            super(message);
361	        }
362	    }
363	}
