259	    public ReservationDocument getDocument(Long id) {
260	        Reservation reservation = getReservation(id);
261	
262	        if (!reservation.getStatus().isPaid()) {
263	            throw new OperationNotAllowedException("Document is only available for paid reservations");
264	        }
265	
266	        return createDocument(reservation);
267	    }
268	
269	    private ReservationDocument createDocument(Reservation reservation) {
270	        Room room = roomRepository.findByNumber(reservation.getRoomNumber()).orElseThrow();
271	
272	        return new ReservationDocument(
273	            "Comprovante de reserva",
274	            reservation.getId(),
275	            reservation.getGuestName(),
276	            reservation.getGuestCpf(),
277	            reservation.getRoomNumber(),
278	            room.getType(),
279	            reservation.getCheckIn(),
280	            reservation.getCheckOut(),
281	            reservation.getNights(),
282	            reservation.getSubtotal(),
283	            reservation.getDiscount(),
284	            reservation.getTotal()
285	        );
286	    }
287	
288	    private String formatDocument(ReservationDocument doc) {
289	        DateTimeFormatter dateFormatter = DateTimeFormatter.ofPattern("dd/MM/yyyy");
290	
291	        String cpf = formatCpf(doc.getGuestCpf());
292	        String checkIn = doc.getCheckIn().format(dateFormatter);
293	        String checkOut = doc.getCheckOut().format(dateFormatter);
294	        String nights = doc.getNights() == 1 ? "1 diária" : doc.getNights() + " diárias";
295	        String subtotal = formatMoney(doc.getSubtotal());
296	
297	        StringBuilder sb = new StringBuilder();
298	        sb.append(String.format("Comprovante de reserva nº %d\n", doc.getReservationId()));
299	        sb.append(String.format("Hóspede: %s (CPF %s)\n", doc.getGuestName(), cpf));
300	        sb.append(String.format("Quarto: %s (%s)\n", doc.getRoomNumber(), doc.getRoomType()));
301	        sb.append(String.format("Entrada: %s | Saída: %s | %s\n", checkIn, checkOut, nights));
302	        sb.append(String.format("Diárias: %s\n", subtotal));
303	
304	        if (doc.getDiscount().compareTo(BigDecimal.ZERO) > 0) {
305	            sb.append(String.format("Desconto: %s\n", formatMoney(doc.getDiscount())));
306	        }
307	
308	        sb.append(String.format("Total: %s", formatMoney(doc.getTotal())));
309	
310	        return sb.toString();
311	    }
312	
313	    private String formatCpf(String cpf) {
314	        if (cpf.length() == 11) {
315	            return String.format("%s.%s.%s-%s",
316	                cpf.substring(0, 3),
317	                cpf.substring(3, 6),
318	                cpf.substring(6, 9),
319	                cpf.substring(9, 11));
320	        }
321	        return cpf;
322	    }
323	
324	    private String formatMoney(BigDecimal value) {
325	        return String.format("R$ %,.2f", value).replace(',', 'X').replace('.', ',').replace('X', '.');
326	    }
