     1	package com.pousada.domain;
     2	
     3	import java.math.BigDecimal;
     4	import java.math.RoundingMode;
     5	import java.time.LocalDate;
     6	import java.time.Month;
     7	import java.time.temporal.ChronoUnit;
     8	
     9	public class Reservation {
    10	    private Long id;
    11	    private final String roomNumber;
    12	    private final String guestName;
    13	    private final String guestEmail;
    14	    private final String guestCpf;
    15	    private final LocalDate checkIn;
    16	    private final LocalDate checkOut;
    17	    private final int guests;
    18	    private final RatePlan ratePlan;
    19	    private final BigDecimal nightlyRate;
    20	    private ReservationStatus status;
    21	    private BigDecimal amountPaid;
    22	    private BigDecimal refund;
    23	
    24	    public Reservation(String roomNumber, String guestName, String guestEmail, String guestCpf,
    25	                       LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan,
    26	                       BigDecimal nightlyRate) {
    27	        this.roomNumber = roomNumber;
    28	        this.guestName = guestName;
    29	        this.guestEmail = guestEmail;
    30	        this.guestCpf = guestCpf;
    31	        this.checkIn = checkIn;
    32	        this.checkOut = checkOut;
    33	        this.guests = guests;
    34	        this.ratePlan = ratePlan;
    35	        this.nightlyRate = nightlyRate;
    36	        this.status = ReservationStatus.PENDING;
    37	        this.amountPaid = BigDecimal.ZERO;
    38	        this.refund = null;
    39	    }
    40	
    41	    public Reservation(Long id, String roomNumber, String guestName, String guestEmail, String guestCpf,
    42	                       LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan,
    43	                       BigDecimal nightlyRate, ReservationStatus status, BigDecimal amountPaid,
    44	                       BigDecimal refund) {
    45	        this.id = id;
    46	        this.roomNumber = roomNumber;
    47	        this.guestName = guestName;
    48	        this.guestEmail = guestEmail;
    49	        this.guestCpf = guestCpf;
    50	        this.checkIn = checkIn;
    51	        this.checkOut = checkOut;
    52	        this.guests = guests;
    53	        this.ratePlan = ratePlan;
    54	        this.nightlyRate = nightlyRate;
    55	        this.status = status;
    56	        this.amountPaid = amountPaid;
    57	        this.refund = refund;
    58	    }
    59	
    60	    public void setId(Long id) {
    61	        this.id = id;
    62	    }
    63	
    64	    public int getNights() {
    65	        return (int) ChronoUnit.DAYS.between(checkIn, checkOut);
    66	    }
    67	
    68	    public BigDecimal getSubtotal() {
    69	        BigDecimal sum = BigDecimal.ZERO;
    70	        LocalDate current = checkIn;
    71	
    72	        while (current.isBefore(checkOut)) {
    73	            BigDecimal nightPrice = nightlyRate;
    74	            if (isHighSeason(current)) {
    75	                nightPrice = nightPrice.multiply(new BigDecimal("1.20"))
    76	                    .setScale(2, RoundingMode.HALF_EVEN);
    77	            }
    78	            sum = sum.add(nightPrice);
    79	            current = current.plusDays(1);
    80	        }
    81	
    82	        return sum.setScale(2, RoundingMode.HALF_EVEN);
    83	    }
    84	
    85	    public BigDecimal getDiscount() {
    86	        BigDecimal subtotal = getSubtotal();
    87	        BigDecimal discount = subtotal.multiply(ratePlan.getDiscountRate())
    88	            .setScale(2, RoundingMode.HALF_EVEN);
    89	        return discount;
    90	    }
    91	
    92	    public BigDecimal getTotal() {
    93	        return getSubtotal().subtract(getDiscount())
    94	            .setScale(2, RoundingMode.HALF_EVEN);
    95	    }
    96	
    97	    private boolean isHighSeason(LocalDate date) {
    98	        Month month = date.getMonth();
    99	        int day = date.getDayOfMonth();
   100	
   101	        if (month == Month.JULY) {
   102	            return true;
   103	        }
   104	
   105	        if (month == Month.DECEMBER && day >= 15) {
   106	            return true;
   107	        }
   108	
   109	        if (month == Month.JANUARY || month == Month.FEBRUARY) {
   110	            return true;
   111	        }
   112	
   113	        return false;
   114	    }
   115	
   116	    public void confirm() {
   117	        if (!status.canConfirm()) {
   118	            throw new IllegalStateException("Cannot confirm reservation in status " + status);
   119	        }
   120	        this.status = ReservationStatus.CONFIRMED;
   121	        this.amountPaid = getTotal();
   122	    }
   123	
   124	    public void checkIn() {
   125	        if (!status.canCheckIn()) {
   126	            throw new IllegalStateException("Cannot check-in reservation in status " + status);
   127	        }
   128	        this.status = ReservationStatus.CHECKED_IN;
   129	    }
   130	
   131	    public void checkOut() {
   132	        if (!status.canCheckOut()) {
   133	            throw new IllegalStateException("Cannot check-out reservation in status " + status);
   134	        }
   135	        this.status = ReservationStatus.CHECKED_OUT;
   136	    }
   137	
   138	    public void cancel() {
   139	        if (!status.canCancel()) {
   140	            throw new IllegalStateException("Cannot cancel reservation in status " + status);
   141	        }
   142	
   143	        this.status = ReservationStatus.CANCELLED;
   144	
   145	        if (ratePlan.isRefundable() && amountPaid.compareTo(BigDecimal.ZERO) > 0) {
   146	            this.refund = amountPaid;
   147	        } else {
   148	            this.refund = BigDecimal.ZERO;
   149	        }
   150	    }
   151	
   152	    public boolean occupiesNight(LocalDate night) {
   153	        return !status.isActive() ? false :
   154	               !night.isBefore(checkIn) && night.isBefore(checkOut);
   155	    }
   156	
   157	    public Long getId() {
   158	        return id;
   159	    }
   160	
   161	    public String getRoomNumber() {
   162	        return roomNumber;
   163	    }
   164	
   165	    public String getGuestName() {
   166	        return guestName;
   167	    }
   168	
   169	    public String getGuestEmail() {
   170	        return guestEmail;
   171	    }
   172	
   173	    public String getGuestCpf() {
   174	        return guestCpf;
   175	    }
   176	
   177	    public LocalDate getCheckIn() {
   178	        return checkIn;
   179	    }
   180	
   181	    public LocalDate getCheckOut() {
   182	        return checkOut;
   183	    }
   184	
   185	    public int getGuests() {
   186	        return guests;
   187	    }
   188	
   189	    public RatePlan getRatePlan() {
   190	        return ratePlan;
   191	    }
   192	
   193	    public BigDecimal getNightlyRate() {
   194	        return nightlyRate;
   195	    }
   196	
   197	    public ReservationStatus getStatus() {
   198	        return status;
   199	    }
   200	
   201	    public BigDecimal getAmountPaid() {
   202	        return amountPaid;
   203	    }
   204	
   205	    public BigDecimal getRefund() {
   206	        return refund;
   207	    }
   208	}
