    11	public class Database {
    12	    private final HikariDataSource dataSource;
    13	
    14	    public Database(String url, String user, String password) {
    15	        HikariConfig config = new HikariConfig();
    16	        config.setJdbcUrl(url);
    17	        config.setUsername(user);
    18	        config.setPassword(password);
    19	        config.setMaximumPoolSize(10);
    20	        this.dataSource = new HikariDataSource(config);
    21	        initializeSchema();
    22	    }
    23	
    24	    private void initializeSchema() {
    25	        try (Connection conn = dataSource.getConnection();
    26	             Statement stmt = conn.createStatement()) {
    27	
    28	            stmt.execute("""
    29	                CREATE TABLE IF NOT EXISTS rooms (
    30	                    number VARCHAR(10) PRIMARY KEY,
    31	                    type VARCHAR(20) NOT NULL,
    32	                    capacity INTEGER NOT NULL,
    33	                    nightly_rate DECIMAL(10,2) NOT NULL
    34	                )
    35	            """);
    36	
    37	            stmt.execute("""
    38	                CREATE TABLE IF NOT EXISTS reservations (
    39	                    id BIGSERIAL PRIMARY KEY,
    40	                    room_number VARCHAR(10) NOT NULL REFERENCES rooms(number),
    41	                    guest_name VARCHAR(255) NOT NULL,
    42	                    guest_email VARCHAR(255) NOT NULL,
    43	                    guest_cpf VARCHAR(14) NOT NULL,
    44	                    check_in DATE NOT NULL,
