    52	                )
    53	            """);
    54	
    55	            stmt.execute("""
    56	                CREATE TABLE IF NOT EXISTS messages (
    57	                    id BIGSERIAL PRIMARY KEY,
    58	                    channel VARCHAR(20) NOT NULL,
    59	                    recipient VARCHAR(255) NOT NULL,
    60	                    subject TEXT NOT NULL,
    61	                    body TEXT NOT NULL,
    62	                    status VARCHAR(20) NOT NULL
    63	                )
    64	            """);
    65	
    66	        } catch (SQLException e) {
    67	            throw new RuntimeException("Failed to initialize database schema", e);
