   190	    public List<Reservation> findRevenueByMonth(YearMonth month) {
   191	        LocalDate startOfMonth = month.atDay(1);
   192	        LocalDate startOfNextMonth = month.plusMonths(1).atDay(1);
   193	
   194	        String sql = """
   195	            SELECT id, room_number, guest_name, guest_email, guest_cpf, check_in, check_out,
   196	                   guests, rate_plan, nightly_rate, status, amount_paid, refund
   197	            FROM reservations
   198	            WHERE check_in >= ?
   199	              AND check_in < ?
   200	              AND (status IN ('CONFIRMED', 'CHECKED_IN', 'CHECKED_OUT')
   201	                   OR (status = 'CANCELLED' AND rate_plan = 'NON_REFUNDABLE' AND amount_paid > 0))
   202	            ORDER BY check_in, id
   203	            """;
   204	
   205	        List<Reservation> reservations = new ArrayList<>();
   206	
   207	        try (Connection conn = database.getConnection();
