    84	            }
    85	
    86	        } catch (SQLException e) {
    87	            throw new RuntimeException("Failed to find room by number", e);
    88	        }
    89	
    90	        return Optional.empty();
    91	    }
    92	
    93	    private Room mapRow(ResultSet rs) throws SQLException {
    94	        String number = rs.getString("number");
    95	        RoomType type = RoomType.valueOf(rs.getString("type"));
    96	        return new Room(number, type);
    97	    }
    98	}

